<?php session_start();require 'includes/db.php';if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}$s=$conn->prepare('SELECT a.id,a.title,a.current_price,a.end_time,MAX(b.amount) AS my_bid FROM bids b JOIN auctions a ON a.id=b.auction_id WHERE b.user_id=? GROUP BY a.id,a.title,a.current_price,a.end_time ORDER BY a.end_time');$s->bind_param('i',$_SESSION['user_id']);$s->execute();$rows=$s->get_result(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My bids · Auctify</title><link rel="stylesheet" href="assets/css/style.css"><link rel="icon" type="image/svg+xml" href="assets/images/auctify-mark.svg"></head><body><?php include 'includes/header.php'; ?><main class="page-container"><h1>My bids</h1><?php if(!$rows->num_rows): ?><p>No bids yet. <a href="index.php">Explore auctions</a>.</p><?php endif; ?><?php while($r=$rows->fetch_assoc()): ?><article class="card"><h3><?= htmlspecialchars($r['title']) ?></h3><p>Your highest bid: K<?= number_format($r['my_bid'],2) ?></p><p>Current price: K<?= number_format($r['current_price'],2) ?></p><p><?= (float)$r['my_bid']===(float)$r['current_price']?'Highest bidder':'Outbid' ?></p><div class="countdown" data-end="<?= strtotime($r['end_time']) ?>"></div><a class="btn" href="auctions/view.php?id=<?= (int)$r['id'] ?>">View auction</a></article><?php endwhile; ?></main><footer>Auctify. · © 2026</footer><script src="assets/js/countdown.js"></script></body></html>